CREATE TABLE faultline.experiment_candidates(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,hypothesis_id uuid NOT NULL,artifact text NOT NULL CHECK(artifact IN('candidate','known_good')),build_digest text NOT NULL,patch_key text,value jsonb NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,hypothesis_id) REFERENCES faultline.hypotheses(workspace_id,case_id,id));
CREATE TABLE faultline.browser_plans(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,hypothesis_id uuid NOT NULL,candidate_id uuid,value jsonb NOT NULL,plan_hash text NOT NULL,hypothesis_hash text NOT NULL,evidence_hashes jsonb NOT NULL,runner_registration_hash text NOT NULL,runner_generation text NOT NULL,mechanism_result_id uuid,mechanism_result_hash text,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,hypothesis_id) REFERENCES faultline.hypotheses(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,candidate_id) REFERENCES faultline.experiment_candidates(workspace_id,case_id,id));
CREATE TABLE faultline.target_grants(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,plan_id uuid NOT NULL,value jsonb NOT NULL,grant_hash text NOT NULL,revision integer NOT NULL DEFAULT 1,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,plan_id) REFERENCES faultline.browser_plans(workspace_id,case_id,id));
CREATE TABLE faultline.test_approvals(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,plan_id uuid NOT NULL,grant_id uuid NOT NULL,value jsonb NOT NULL,approval_hash text NOT NULL,revision integer NOT NULL DEFAULT 1,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,plan_id) REFERENCES faultline.browser_plans(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,grant_id) REFERENCES faultline.target_grants(workspace_id,case_id,id));
CREATE TABLE faultline.verification_runs(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,plan_id uuid NOT NULL,approval_id uuid NOT NULL,grant_id uuid NOT NULL,job_id uuid NOT NULL,fence uuid NOT NULL,nonce uuid NOT NULL UNIQUE,expires_at timestamptz NOT NULL,runner_generation text NOT NULL,expected jsonb NOT NULL,request_hash text NOT NULL,status text NOT NULL,receipt jsonb,receipt_hash text,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,fence),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,job_id) REFERENCES faultline.jobs(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,plan_id) REFERENCES faultline.browser_plans(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,approval_id) REFERENCES faultline.test_approvals(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,grant_id) REFERENCES faultline.target_grants(workspace_id,case_id,id));
CREATE TABLE faultline.verification_results(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,plan_id uuid NOT NULL,run_id uuid NOT NULL UNIQUE,job_id uuid NOT NULL UNIQUE,value jsonb NOT NULL,result_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,run_id) REFERENCES faultline.verification_runs(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,plan_id) REFERENCES faultline.browser_plans(workspace_id,case_id,id));
ALTER TABLE faultline.browser_plans ADD CONSTRAINT mechanism_binding FOREIGN KEY(workspace_id,case_id,mechanism_result_id) REFERENCES faultline.verification_results(workspace_id,case_id,id);
CREATE TABLE faultline.verification_artifacts(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,run_id uuid NOT NULL,result_id uuid,object_key text NOT NULL,sha256 text NOT NULL,size_bytes bigint NOT NULL,media_type text NOT NULL,arm text NOT NULL,cohort text NOT NULL,repeat integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,arm,cohort,repeat),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,run_id) REFERENCES faultline.verification_runs(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,result_id) REFERENCES faultline.verification_results(workspace_id,case_id,id));
DO $scope$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['experiment_candidates','browser_plans','target_grants','test_approvals','verification_runs','verification_results','verification_artifacts'] LOOP
 EXECUTE format('ALTER TABLE faultline.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE faultline.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_scope ON faultline.%I USING(workspace_id::text=current_setting(''faultline.workspace_id'',true)) WITH CHECK(workspace_id::text=current_setting(''faultline.workspace_id'',true))',t);
END LOOP;END $scope$;
GRANT SELECT,INSERT ON faultline.experiment_candidates,faultline.browser_plans,faultline.target_grants,faultline.test_approvals,faultline.verification_runs,faultline.verification_results,faultline.verification_artifacts TO faultline_api;
GRANT UPDATE(value,grant_hash,revision) ON faultline.target_grants TO faultline_api;
GRANT UPDATE(value,approval_hash,revision) ON faultline.test_approvals TO faultline_api;
GRANT UPDATE(status,receipt,receipt_hash,error_code,updated_at) ON faultline.verification_runs TO faultline_api;
GRANT UPDATE(result_id) ON faultline.verification_artifacts TO faultline_api;
